import { pageSections } from './sections';

export const SUMMARY_GLOBAL_MOVES_KEYS = ['corona'] as const;

export const SUMMARY_GROWTH_LEVER_KEYS = ['nonAlcBeer', 'beyondBeer'] as const;

export const SUMMARY_MUST_WIN_COUNTRIES = [
  'BRA',
  'USA',
  'MEX',
  'CHN',
  'ZAF',
] as const;

export type SummaryMustWinCountryCode =
  (typeof SUMMARY_MUST_WIN_COUNTRIES)[number];

export const SUMMARY_CORONA_SECTION_OVERRIDES = {
  coverSection: pageSections.coronaCover,
  section: pageSections.coronaSegments,
  volumeCountriesBreakdown: pageSections.coronaVolumeCountriesBreakdown,
};

export const SUMMARY_NON_ALC_BEER_SECTION_OVERRIDES = {
  coverSection: pageSections.nonAlcBeerCover,
  section: pageSections.nonAlcBeerGlobalMoves,
  volumeCountriesBreakdown: pageSections.nonAlcBeerVolumeCountriesBreakdown,
};

export const SUMMARY_BEYOND_BEER_SECTION_OVERRIDES = {
  coverSection: pageSections.beyondBeerCover,
  section: pageSections.beyondBeerGlobalMoves,
  volumeCountriesBreakdown: pageSections.beyondBeerVolumeCountriesBreakdown,
};

export const SUMMARY_GROWTH_LEVER_SECTION_OVERRIDES = {
  nonAlcBeer: SUMMARY_NON_ALC_BEER_SECTION_OVERRIDES,
  beyondBeer: SUMMARY_BEYOND_BEER_SECTION_OVERRIDES,
} as const;

export const SUMMARY_COUNTRY_SECTION_MAP: Record<
  SummaryMustWinCountryCode,
  string
> = {
  BRA: pageSections.braVolume,
  USA: pageSections.usaVolume,
  MEX: pageSections.mexVolume,
  CHN: pageSections.chnVolume,
  ZAF: pageSections.zafVolume,
};
